import numpy as np

class OnlineOLS:
    def __init__(self, p):
        self.P = np.eye(p) * 1e8
        self.b = np.zeros(p)

    def add(self, x, y):
        x = np.asarray(x, float)
        Px = self.P @ x
        self.P = self.P - np.outer(Px, Px) / (1.0 + x @ Px)
        self.b = self.b + (self.P @ x) * (y - x @ self.b)

    def remove(self, x, y):
        x = np.asarray(x, float)
        Px = self.P @ x
        self.P = self.P + np.outer(Px, Px) / (1.0 - x @ Px)
        self.b = self.b - (self.P @ x) * (y - x @ self.b)

    def coef(self):
        return self.b.copy()
